var defaultVariable = {
    "action": ""
  }  
var variable = source.getVariable();
  if(variable != "" && variable != null){
    try{
      variable = JSON.parse(variable);
    } catch(err) {
      java.log(err);
      variable = defaultVariable;
    }
  }
if(variable.action != "" && variable.action != null && variable.action != undefined){
        var cover = "https://" + variable.action + result;
        var r = `当前服务器：\nvariable.action`;
        java.toast(r);
   } else {
        var cover  = "https://www.qbmfxs.com" + result;
