@js:
var sort = [],
    header = eval(getHeaders(source)),
    src = java.connect(
    	baseUrl, header).body(),
    b = src.match(/(html_b|dstr)="(.*?)"/);
if (b) src = dec(b);
var doc = org.jsoup.Jsoup.parse(src),
    a = doc.select("ul.nav.nav-pills li a");
for (let i = 1; i < a.size(); i++) {
    let fl = ({
        "title": a[i].text(),
        "url": `${a[i].attr("href")}<,{{page}}>`,
        "style": {
            "layout_flexGrow": 1,
            "layout_flexShrink": 1,
            "layout_alignSelf": "auto",
            "layout_flexBasisPercent": 0.2,
            "layout_wrapBefore": false
        }
    });
    sort.push(fl);
}

JSON.stringify(sort);

